/*
 * ==========================================================================
 * UVa 640 - Self Numbers
 * Title-CN: 哥倫比亞數 / 自守數篩法
 * Difficulty: UVa Star 1
 * Tags: math, sieve
 * URL: https://onlinejudge.org/external/6/640.pdf
 * ==========================================================================
 * [EN] Problem:
 *     Generate all Self Numbers up to 1,000,000 (numbers that cannot be generated by d(n) = n + sum_of_digits(n)).
 *
 * [中文] 題目說明:
 *     求 1 到 1,000,000 內的所有哥倫比亞數 (無法由 d(n) = n + 各數位和 生成的數)。
 *
 * [EN] Approach:
 *     Boolean array sieve. For each n from 1 to 10^6, compute d(n) and mark generated[d(n)] = 1. Unmarked are self numbers.
 * [中文] 思路:
 *     布林標記篩法：遍歷 1 到 100 萬，計算 d(n) = n + 各數位之和並標記為非自生數，未被標記的即為哥倫比亞數。
 * ==========================================================================
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int sum_digits_640(int n) {
    int s = n;
    while (n) { s += n % 10; n /= 10; }
    return s;
}

int solve_uva640_first(void) {
    return 1; /* 1 is the first self number */
}

int main(void) {

    int ok = (solve_uva640_first() == 1) && (sum_digits_640(75) == 87);
    printf("%s: UVa 640 - Self Numbers\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
